export fn kth_next_greater_element(v:[*]const i64,n:usize)i64{if(n<2 or n>8)return -1;const k=v[0];if(k<1 or k>7)return -1;const m=n-1;for(1..n)|q|{if(v[q]< -15 or v[q]>15)return -1;}var count:i64=0;for(0..m)|i|{var cur=v[i+1];var pos=i+1;var ok=true;var z:i64=0;while(z<k):(z+=1){while(pos<m and v[pos+1]<=cur):(pos+=1){};if(pos==m){ok=false;break;}cur=v[pos+1];pos+=1;}if(ok)count+=1;}return count;}
